       (4, 0, 'Ручний інструмент', 12);
SELECT setval(pg_get_serial_sequence('прайс_categories', 'id'), (SELECT max(id) FROM прайс_categories));
CREATE OR REPLACE VIEW прайс_categories_visible AS
SELECT c.id, COALESCE(p.name, '') AS parent, c.name, c.excel_row
FROM прайс_categories c
         LEFT JOIN прайс_categories p ON p.id = c.parent_id AND c.parent_id > 0
WHERE c.is_visible
  AND (c.parent_id = 0 OR p.is_visible);
COMMENT ON VIEW прайс_categories_visible IS 'Category rows of sheet "Прайс", depth 2; parent_id = 0 is the top level';
COMMENT ON COLUMN прайс_categories_visible.parent IS 'parent category name, empty for the top level';

CREATE OR REPLACE FUNCTION find_прайс_categories(value character varying, counter integer, _id integer DEFAULT 0)
    RETURNS TABLE
            (
                id        integer,
                parent    character varying,
                name      character varying,
                excel_row integer
            )
    LANGUAGE plpgsql
AS
$$
BEGIN
    IF counter <= 0 THEN
        counter = 1000;
    END IF;

    RETURN QUERY
        SELECT v.id, v.parent, v.name, v.excel_row
        FROM прайс_categories_visible v
        WHERE CASE WHEN _id > 0 THEN v.id = _id ELSE v.name ~ value END
        ORDER BY v.id
            FETCH FIRST counter ROWS ONLY;
END;
$$;
COMMENT ON FUNCTION find_прайс_categories(character varying, integer, integer) IS 'Search visible categories of прайс_categories by name (regular expression) or by id';

CREATE TABLE IF NOT EXISTS прайс
(
    id           INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    category_id  INTEGER REFERENCES прайс_categories (id),
    найменування CHARACTER VARYING NOT NULL DEFAULT '', -- A: Найменування
    фото         CHARACTER VARYING NOT NULL DEFAULT '', -- B: Фото
    артикул      CHARACTER VARYING NOT NULL DEFAULT '', -- C: Артикул
    ціна_грн     NUMERIC,                               -- D: Ціна, грн
    наявність    CHARACTER VARYING NOT NULL DEFAULT '', -- E: Наявність
    is_visible   BOOLEAN           NOT NULL DEFAULT true
);
COMMENT ON TABLE прайс IS E'ТОВ "Світ інструменту"\nПрайс-лист на 01.10.2026\nЦіни вказані з ПДВ';
COMMENT ON COLUMN прайс.category_id IS 'category (прайс_categories)';
COMMENT ON COLUMN прайс.найменування IS 'Найменування';
COMMENT ON COLUMN прайс.фото IS 'Фото {"view_url": "<a href=''%s'' data-fancybox hx-swap=''none'' ><img src=''%[1]s''></a>"}';
COMMENT ON COLUMN прайс.артикул IS 'Артикул';
COMMENT ON COLUMN прайс.ціна_грн IS 'Ціна, грн';
COMMENT ON COLUMN прайс.наявність IS 'Наявність';

