CREATE OR REPLACE VIEW прайс_visible AS
SELECT t.id, COALESCE(c.name, '') AS category, t.найменування, t.фото, t.артикул, t.ціна_грн, t.наявність
FROM прайс t
         LEFT JOIN прайс_categories c ON c.id = t.category_id
WHERE t.is_visible
  AND (t.category_id IS NULL OR c.is_visible);
COMMENT ON VIEW прайс_visible IS E'ТОВ "Світ інструменту"\nПрайс-лист на 01.10.2026\nЦіни вказані з ПДВ';
COMMENT ON COLUMN прайс_visible.category IS 'category name (прайс_categories), empty if none';
COMMENT ON COLUMN прайс_visible.найменування IS 'Найменування';
COMMENT ON COLUMN прайс_visible.фото IS 'Фото {"view_url": "<a href=''%s'' data-fancybox hx-swap=''none'' ><img src=''%[1]s''></a>"}';
COMMENT ON COLUMN прайс_visible.артикул IS 'Артикул';
COMMENT ON COLUMN прайс_visible.ціна_грн IS 'Ціна, грн';
COMMENT ON COLUMN прайс_visible.наявність IS 'Наявність';

CREATE OR REPLACE FUNCTION find_прайс(value character varying, counter integer, _id integer DEFAULT 0)
    RETURNS TABLE
            (
                id           integer,
                category     character varying,
                найменування character varying,
                фото         character varying,
                артикул      character varying,
                ціна_грн     numeric,
                наявність    character varying
            )
    LANGUAGE plpgsql
AS
$$
BEGIN
    IF counter <= 0 THEN
        counter = 1000;
    END IF;

    RETURN QUERY
        SELECT v.id, v.category, v.найменування, v.фото, v.артикул, v.ціна_грн, v.наявність
        FROM прайс_visible v
        WHERE CASE WHEN _id > 0 THEN v.id = _id ELSE v.артикул ~ value END
        ORDER BY v.id
            FETCH FIRST counter ROWS ONLY;
END;
$$;
COMMENT ON FUNCTION find_прайс(character varying, integer, integer) IS 'Search visible rows of прайс by артикул (regular expression) or by id';

COMMIT;
